const crypto = require('crypto');

const secret = $env.JWT_SECRET || '__REDACTED_JWT_SECRET__';

// Input: { authorization: 'Bearer <token>' }
const raw = ($json.authorization || '').trim();
const m   = raw.match(/^Bearer\s+(.+)$/i);
if (!m) {
  return [{ json: { ok: false, status: 401, error: 'missing_bearer', code: 'invalid_token' } }];
}
const token = m[1];
const parts = token.split('.');
if (parts.length !== 3) {
  return [{ json: { ok: false, status: 401, error: 'malformed_token', code: 'invalid_token' } }];
}

const [h, p, sig] = parts;
const expected = crypto
  .createHmac('sha256', secret)
  .update(`${h}.${p}`)
  .digest('base64')
  .replace(/=+$/g, '').replace(/\+/g, '-').replace(/\//g, '_');

if (expected !== sig) {
  return [{ json: { ok: false, status: 401, error: 'bad_signature', code: 'invalid_token' } }];
}

let payload;
try {
  const pad = p.length % 4 ? '='.repeat(4 - (p.length % 4)) : '';
  const b64 = (p + pad).replace(/-/g, '+').replace(/_/g, '/');
  payload = JSON.parse(Buffer.from(b64, 'base64').toString('utf8'));
} catch (e) {
  return [{ json: { ok: false, status: 401, error: 'malformed_payload', code: 'invalid_token' } }];
}

const now = Math.floor(Date.now() / 1000);
if (payload.exp && payload.exp < now) {
  return [{ json: { ok: false, status: 401, error: 'expired', code: 'token_expired' } }];
}
if (!payload.sub) {
  return [{ json: { ok: false, status: 401, error: 'missing_sub', code: 'invalid_token' } }];
}

return [{ json: { ok: true, user_id: payload.sub, email: payload.email || null } }];
